    const rows = withS.filter(x => (!f.s || F.norm(x.c.code + ' ' + Q.tenant(x.c.tenantId).name + ' ' + Q.tenant(x.c.tenantId).phone).includes(F.norm(f.s))) && (!f.buildingId || x.c.buildingId === f.buildingId) && (!f.status || (f.status === 'active' ? ['active', 'expiring'].includes(x.s) : x.s === f.status)) && (!f.exp || (x.s === 'expiring')) && (!f.managerId || x.c.managerId === f.managerId)).sort((a, b) => F.cmp(b.c.createdAt || b.c.start, a.c.createdAt || a.c.start));
