    /* OCR (template HĐ cho thuê phòng): đơn giá dịch vụ → mã dịch vụ catalog (điện/nước tính theo công tơ nên không đưa vào dịch vụ HĐ); giá lấy từ hợp đồng nếu có, số xe → GUIXE qty + dòng xe */
    const ocrVehicles = ocr ? Math.max(0, Math.min(10, F.num(of('vehicleCount')))) : 0; const ocrSvc = ocr ? { INTERNET: F.num(of('svc_internet')), QUANLY: F.num(of('svc_common')), GUIXE: ocrVehicles ? (F.num(of('svc_ebike')) || F.num(of('svc_evcar'))) : 0 } : null;
    let services = draft ? Q.contractServices(draft.id).map(s => Object.assign({}, s)) : deal ? (deal.serviceIds || []).map(id => { const s = Q.service(id); return s.id ? { serviceId: s.id, name: s.name, unit: s.unit, price: s.price, qty: 1, note: '' } : null; }).filter(Boolean).concat((deal.extraServices || []).map(x => ({ serviceId: null, name: x.name, unit: x.unit || 'Tháng', price: x.price, qty: x.qty || 1, note: 'Theo thỏa thuận chốt thuê' }))) : ocrSvc ? St.where('services', s => s.status === 'active' && ocrSvc[s.code]).map(s => ({ serviceId: s.id, name: s.name, unit: s.unit, price: ocrSvc[s.code] || s.price, qty: s.code === 'GUIXE' ? ocrVehicles || 1 : 1, note: 'Từ trích xuất' + (ocrSvc[s.code] && ocrSvc[s.code] !== s.price ? ' – đơn giá theo HĐ' : '') })) : (room0 ? (room0.defaultServiceIds || []).map(id => { const s = Q.service(id); return { serviceId: s.id, name: s.name, unit: s.unit, price: Q.servicePrice(s.id, room0.buildingId, d.start || F.today()), qty: 1, note: s.code === 'INTERNET' ? 'FPT' : s.code === 'GUIXE' ? 'Tầng hầm B1' : '' }; }) : []);
