    const SEC_STEP = [0, 0, 0, 1, 1, 1, 1, 1, 1]; root.querySelectorAll('#cf .fs').forEach((el, i) => { el.dataset.step = SEC_STEP[i] != null ? SEC_STEP[i] : 1; });
