    const acts = []; if (c.status === 'draft') acts.push(U.btn({ label: 'Sửa nháp', icon: 'pencil', cls: 'btn-outline', act: 'edit' }), U.btn({ label: 'Kích hoạt', icon: 'check-circle', cls: 'btn-primary', act: 'activate' }));
    if (c.status === 'active') acts.push(U.btn({ label: 'Tạo hóa đơn', icon: 'receipt', cls: 'btn-primary', act: 'inv' }), U.btn({ label: 'Gia hạn', icon: 'refresh', cls: 'btn-outline', act: 'renew' }), U.btn({ label: 'Kết thúc hợp đồng', icon: 'x-circle', cls: 'btn-ghost', act: 'terminate', attrs: { 'data-guide': 'contract-terminate', style: 'color:var(--red)' } }));
    if (c.status === 'ended' && !rf && !c.renewedToId) acts.push(U.btn({ label: 'Lập phương án hoàn cọc', icon: 'hand-coins', cls: 'btn-primary', act: 'refund' }));
    if (rf) acts.push(U.btn({ label: 'Hồ sơ hoàn cọc ' + rf.code, icon: 'hand-coins', cls: 'btn-outline', act: 'go-refund' }));
