    root.innerHTML = `${U.pageHead({ back: '#/contracts', title: esc(c.code), chips: ' ' + Q.chip('contract', s, 'lg'), sub: `${esc(t.name)} • ${esc(r.code)} - ${esc(b.name)} • ${F.date(c.start)} – ${F.date(c.actualEnd || c.end)}${c.renewedFromId ? ' • Gia hạn từ ' + U.link('#/contracts/' + c.renewedFromId, Q.contract(c.renewedFromId).code) : ''}${c.renewedToId ? ' • Đã gia hạn → ' + U.link('#/contracts/' + c.renewedToId, Q.contract(c.renewedToId).code) : ''}`, acts })}
    <div class="grid grid-4 mb16">${U.kpi({ label: 'Giá thuê thực tế', value: F.vnd(c.price), cap: 'Niêm yết ' + F.vnd(c.listPrice) + ' đ', icon: 'dollar', tone: 'amber' })}${U.kpi({ label: 'Tiền cọc', value: F.vnd(c.deposit), cap: rf ? 'Hoàn cọc: ' + Q.label('refund', rf.status) : ledger.length ? (dbal.unpaid > 0 ? 'Còn phải thu ' + F.vnd(dbal.unpaid) : 'Đang giữ ' + F.vnd(dbal.holding)) + ' · ledger ' + ledger.length + ' bút toán' : (c.status === 'active' ? (c.depositPaymentId ? 'Đã thu ' + F.date(c.depositPaidAt) + ' · đang giữ' : 'Đang giữ · chưa ghi nhận thu') : '-'), icon: 'shield', tone: 'blue' })}${U.kpi({ label: 'Công nợ', value: F.vnd(debt), cap: invs.length + ' hóa đơn', icon: 'alert-circle', tone: 'red', valueCls: debt ? 'red' : '' })}${U.kpi({ label: c.status === 'active' ? 'Còn lại' : 'Trạng thái', value: c.status === 'active' ? F.daysUntil(c.end) + ' ngày' : Q.label('contract', s), cap: c.status === 'active' ? 'Kết thúc ' + F.date(c.end) + (s === 'expiring' ? ' – sắp hết hạn (≤35 ngày)' : '') : (c.actualEnd ? 'Kết thúc thực tế ' + F.date(c.actualEnd) : ''), icon: 'clock', tone: s === 'expiring' ? 'amber' : 'green' })}</div>
    ${U.tabs([{ key: 'overview', label: 'Tổng quan' }, { key: 'members', label: 'Người thuê', count: cts.filter(x => !x.to).length }, { key: 'services', label: 'Dịch vụ & xe' }, { key: 'deposit', label: 'Cọc', count: ledger.length }, { key: 'terms', label: 'Điều khoản & bàn giao' }, { key: 'invoices', label: 'Hóa đơn', count: invs.length }, { key: 'docs', label: 'Tài liệu' }, { key: 'log', label: 'Lịch sử' }], tab)}<div id="tab-body"></div>`;
    const body = root.querySelector('#tab-body');
    if (tab === 'overview') body.innerHTML = `<div class="grid grid-2">${U.card({ title: 'Thông tin hợp đồng', icon: 'file-text', body: U.kv([['Mã HĐ', esc(c.code) + (c.contractNo ? ' <span class="muted small">· số HĐ giấy ' + esc(c.contractNo) + '</span>' : '')], ['Nguồn', c.source === 'ocr' && ocrJob ? U.chip('OCR ' + ocrJob.code, 'purple') + ' ' + U.link('#/contracts/ocr?id=' + ocrJob.id, 'Xem job') : (c.source === 'ocr' ? U.chip('OCR', 'purple') : 'Nhập tay')], ['Trạng thái', Q.chip('contract', s)], ['Kỳ hợp đồng', Q.contractTermLabel(c)], ['Ngày ký', F.date(c.signedDate)], ['Ngày bắt đầu', F.date(c.start)], ['Ngày kết thúc', F.date(c.end)], ['Kết thúc thực tế', c.actualEnd ? F.date(c.actualEnd) : '-'], ['Lý do kết thúc', esc(c.endReason || '-')], ['Chu kỳ thanh toán', 'Hàng tháng, ngày ' + F.pad(c.payDay)], ['Người phụ trách', esc(Q.userName(c.managerId))], ['Ghi chú / điều khoản', esc(c.note || '-') + ' <a class="link small" data-act="edit-note">' + I('pencil') + ' Sửa</a>' + (c.noteAt ? '<div class="xs muted">Cập nhật ' + F.datetime(c.noteAt) + (c.noteBy ? ' · ' + esc(c.noteBy) : '') + '</div>' : '')]], 'one') })}${U.card({ title: 'Khách thuê & phòng', icon: 'user', body: `<div class="row gap12 mb12">${U.avatar(t.name, 'lg')}<div><b style="font-size:15px;color:var(--text)">${U.link('#/tenants/' + t.id, esc(t.name))}</b><div class="small muted">${esc(t.code)} · ${I('phone')} ${esc(t.phone)}</div></div></div>${U.kv([['Phòng', U.link('#/rooms/' + r.id, esc(r.code))], ['Mã tòa · phòng', esc(F.roomRef(b, r))], ['Tòa nhà', U.link('#/buildings/' + b.id, esc(b.name))], ['Loại / diện tích', esc(r.type) + ' · ' + r.area + ' m²'], ['Trạng thái phòng', Q.chipDot('room', r.status)], ['Tổng tiền hàng tháng (ước)', F.vnd(Q.contractMonthly(c)) + ' đ']], 'one')}` })}</div>`;
    if (tab === 'services') body.innerHTML = U.card({ title: 'Dịch vụ áp dụng & phương tiện', icon: 'sliders', sub: 'Snapshot giá theo hợp đồng (BR-21); số xe không giới hạn (BR-05)', bodyCls: 'tight', body: `<table class="tbl compact"><thead><tr><th>#</th><th>Dịch vụ</th><th>Đơn vị</th><th class="num">Đơn giá</th><th class="num">Số lượng</th><th class="num">Thành tiền/tháng</th><th>Ghi chú</th></tr></thead><tbody>${svcs.map((x, i) => `<tr><td>${i + 1}</td><td>${esc(x.name)}</td><td>${esc(x.unit)}</td><td class="num">${F.vnd(x.price)}</td><td class="num">${x.qty}</td><td class="num">${F.vnd(x.price * x.qty)}</td><td>${esc(x.note || '-')}</td></tr>`).join('')}<tr><td colspan="5"><b>Điện, Nước</b></td><td colspan="2" class="muted">Theo chỉ số hàng tháng – nhập tại Tạo hóa đơn theo kỳ</td></tr></tbody></table><div class="fs"><div class="fs-h">${I('car')}Phương tiện (${(c.vehicles || []).length})</div>${(c.vehicles || []).length ? `<table class="tbl compact"><thead><tr><th>#</th><th>Loại</th><th>Biển số</th></tr></thead><tbody>${c.vehicles.map((v, i) => `<tr><td>${i + 1}</td><td>${esc(v.type)}</td><td><b>${esc(v.plate || '-')}</b></td></tr>`).join('')}</tbody></table>` : '<div class="muted small">Chưa đăng ký phương tiện.</div>'}</div>` });
    if (tab === 'members') body.innerHTML = U.card({ title: 'Người thuê theo hợp đồng (§4.8)', icon: 'users', sub: 'Khách đứng tên + người ở cùng – mỗi người là một hồ sơ khách riêng liên kết hợp đồng (CONTRACT_TENANT)', actions: c.status !== 'ended' ? U.btn({ label: 'Thêm người ở cùng', icon: 'user-plus', size: 'btn-sm', cls: 'btn-primary', act: 'add-ct' }) : '', bodyCls: 'tight', body: `<table class="tbl compact"><thead><tr><th>#</th><th>Vai trò</th><th>Họ tên</th><th>Hồ sơ khách</th><th>SĐT</th><th>CCCD</th><th>Ngày sinh</th><th>Quan hệ</th><th>Từ – đến</th><th></th></tr></thead><tbody>${cts.map((m, i) => { const tt = m.tenantId ? Q.tenant(m.tenantId) : null; return `<tr class="${m.to ? 'muted' : ''}"><td>${i + 1}</td><td>${Q.chip('contractTenantRole', m.role)}</td><td><b>${esc(tt ? tt.name : m.name)}</b></td><td>${tt ? U.link('#/tenants/' + tt.id, esc(tt.code)) : '<span class="chip amber">Chưa liên kết</span> ' + U.btn({ label: 'Liên kết', size: 'btn-sm', cls: 'btn-ghost', act: 'link-ct', attrs: { 'data-id': m.id } })}</td><td>${esc(tt ? tt.phone : (m.phone || '-'))}</td><td>${esc(tt ? (tt.idNumber || '-') : (m.idNumber || '-'))}</td><td>${(tt ? tt.dob : m.dob) ? F.date(tt ? tt.dob : m.dob) : '-'}</td><td>${esc(m.relation || (m.role === 'primary' ? 'Người thuê (chính)' : '-'))}</td><td class="xs">${F.date(m.from || c.start)} – ${m.to ? F.date(m.to) : 'nay'}</td><td class="tr">${m.role === 'cohabitant' && !m.to ? U.iconBtn('log-out', 'rm-ct', 'Ghi nhận rời đi', { 'data-id': m.id }) : ''}</td></tr>`; }).join('') || '<tr><td colspan="10" class="muted tc">Chưa có</td></tr>'}</tbody></table>${mbs.length > cts.length ? '<div class="xs muted" style="padding:8px 12px">Thành viên nhập tay cũ: ' + mbs.map(m => esc(m.name)).join(', ') + '</div>' : ''}` });
