    if (tab === 'docs') { const docs = St.where('documents', d => d.entityType === 'contract' && d.entityId === c.id); body.innerHTML = U.card({ title: 'Tài liệu hợp đồng', icon: 'folder', actions: U.btn({ label: 'Tải lên HĐ đã ký', icon: 'upload', size: 'btn-sm', cls: 'btn-primary', act: 'upload' }), body: docs.length ? `<div class="file-list">${docs.map(d => U.fileItem(d, U.iconBtn('trash', 'rm-doc', 'Xóa', { 'data-id': d.id }))).join('')}</div>` : U.empty({ icon: 'folder', title: 'Chưa có file hợp đồng', text: 'Tải lên bản hợp đồng đã ký (PDF/JPG) hoặc tạo HĐ từ OCR để file tự gắn vào đây (docType contract, nguồn OCR).' }) }); }
