    U.bind(root, { tab: (el) => { TH.router.replaceQuery({ tab: el.dataset.key }); TH.router.refresh(); }, 'edit-note': () => { const m = U.modal({ title: 'Ghi chú / điều khoản hợp đồng', size: 'sm', body: U.textarea({ name: 'note', value: c.note || '', rows: 5, placeholder: 'Điều khoản đặc biệt, thỏa thuận thêm…' }), footer: U.btn({ label: 'Hủy', act: 'c' }) + U.btn({ label: 'Lưu', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { c: () => m.close(), s: () => { X.updateContractNote(c.id, m.data().note); m.close(); U.toast('ok', 'Đã lưu ghi chú hợp đồng'); } }); }, edit: () => TH.go('#/contracts/new?id=' + c.id), activate: () => TH.go('#/contracts/new?id=' + c.id + '&step=5'), inv: () => TH.go('#/invoices/batch?buildingId=' + c.buildingId + '&room=' + c.roomId), renew: () => Fm.renew(c), terminate: () => Fm.terminate(c), refund: () => TH.go('#/refunds/new?contract=' + c.id), 'go-refund': () => TH.go('#/refunds/' + rf.id), pdf: () => U.fakePdf('Hop dong ' + c.code, ['Khách: ' + t.name, 'Phòng: ' + r.code + ' – ' + b.name, 'Thời hạn: ' + F.date(c.start) + ' – ' + F.date(c.end), 'Giá thuê: ' + F.vnd(c.price), 'Cọc: ' + F.vnd(c.deposit)]), upload: () => Fm.upload('contract', c.id), 'rm-doc': (el) => X.removeDocument(el.dataset.id), more: (el) => cMenu(el, c),
      'add-ct': () => { const opts = St.all('tenants').filter(x => x.id !== c.tenantId && !cts.some(m => m.tenantId === x.id && !m.to)).sort((a, z) => F.cmp(a.name, z.name)).map(x => [x.id, x.name + ' · ' + (x.phone || '') + ' (' + x.code + ')']); const m = U.modal({ title: 'Thêm người ở cùng', sub: 'Chọn hồ sơ khách có sẵn hoặc tạo hồ sơ mới (match CCCD → SĐT → tên+ngày sinh)', body: `<div class="form-grid">${U.field({ label: 'Khách có sẵn', input: U.select({ name: 'tenantId', all: '— Tạo hồ sơ mới —', options: opts }), cls: 'span2' })}${U.field({ label: 'Họ tên (mới)', input: U.input({ name: 'name' }) })}${U.field({ label: 'SĐT (mới)', input: U.input({ name: 'phone' }) })}${U.field({ label: 'CCCD', input: U.input({ name: 'idNumber' }) })}${U.field({ label: 'Ngày sinh', input: U.date({ name: 'dob' }) })}${U.field({ label: 'Quan hệ', input: U.select({ name: 'relation', value: 'Bạn cùng phòng', options: ['Vợ/Chồng', 'Bạn cùng phòng', 'Con', 'Anh/Chị/Em', 'Khác'] }) })}${U.field({ label: 'Từ ngày', input: U.date({ name: 'from', value: F.today() }) })}</div>`, footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Thêm', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { try { const d = m.data(); X.addContractTenant({ contractId: c.id, tenantId: d.tenantId || null, newTenant: d.tenantId ? null : { name: d.name, phone: d.phone, idNumber: d.idNumber, dob: d.dob }, relation: d.relation, from: d.from }); m.close(); U.toast('ok', 'Đã thêm người ở cùng'); TH.router.refresh(); } catch (e) { U.toast('err', 'Không thêm được', e.message); } } }); },
      'rm-ct': async (el) => { if (!(await U.confirm({ title: 'Ghi nhận người ở cùng rời đi?', text: 'Hồ sơ khách vẫn giữ nguyên; liên kết với hợp đồng kết thúc hôm nay.' }))) return; try { X.removeContractTenant(el.dataset.id); TH.router.refresh(); } catch (e) { U.toast('err', 'Lỗi', e.message); } },
      'link-ct': (el) => { const ct = St.rawGet('contractTenants', el.dataset.id); const r = Q.tenantMatch({ name: ct.name, phone: ct.phone, idNumber: ct.idNumber, dob: ct.dob }); const opts = St.all('tenants').sort((a, z) => F.cmp(a.name, z.name)).map(x => [x.id, x.name + ' · ' + (x.phone || '') + ' (' + x.code + ')']); const m = U.modal({ title: 'Liên kết hồ sơ khách', sub: esc(ct.name) + (r.match ? ' – gợi ý ' + esc(r.match.name) + ' (' + esc(r.matchBy) + ')' : ' – không tìm thấy hồ sơ khớp'), size: 'sm', body: U.field({ label: 'Hồ sơ khách', input: U.select({ name: 'tenantId', value: r.match ? r.match.id : '', placeholder: 'Chọn…', options: opts }) }) + '<div class="xs muted mt8">Hoặc tạo hồ sơ mới tại Khách thuê rồi liên kết.</div>', footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Liên kết', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { try { X.linkContractTenant(ct.id, m.data().tenantId); m.close(); TH.router.refresh(); } catch (e) { U.toast('err', 'Lỗi', e.message); } } }); },
      'dep-recv': () => { const m = U.modal({ title: 'Ghi nhận thu cọc', sub: 'Còn phải thu ' + F.vnd(dbal.unpaid) + ' – ghi RECEIVED vào Deposit Ledger', size: 'sm', body: `<div class="form-grid">${U.field({ label: 'Số tiền', req: true, input: U.money({ name: 'amount', value: dbal.unpaid }) })}${U.field({ label: 'Ngày thu', req: true, input: U.date({ name: 'date', value: F.today() }) })}${U.field({ label: 'Phương thức', input: U.select({ name: 'method', value: 'Chuyển khoản', options: ['Chuyển khoản', 'Tiền mặt'] }) })}${U.field({ label: 'Mã tham chiếu', input: U.input({ name: 'ref' }) })}</div>`, footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Ghi nhận', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { try { const d = m.data(); X.recordDepositReceived({ contractId: c.id, amount: F.num(d.amount), date: d.date, method: d.method, ref: d.ref }); m.close(); U.toast('ok', 'Đã ghi nhận thu cọc'); TH.router.refresh(); } catch (e) { U.toast('err', 'Không ghi được', e.message); } } }); },
      'edit-terms': () => { const t0 = pterms || {}; const m = U.modal({ title: 'Điều khoản thanh toán', body: `<div class="form-grid">${U.field({ label: 'Ngày gửi thông báo', input: U.input({ name: 'notifyDay', type: 'number', value: t0.notifyDay || 25 }) })}${U.field({ label: 'Thanh toán từ ngày', input: U.input({ name: 'payFrom', type: 'number', value: t0.payFrom || 25 }) })}${U.field({ label: 'Đến ngày', input: U.input({ name: 'payTo', type: 'number', value: t0.payTo || 30 }) })}${U.field({ label: 'Hình thức', input: U.select({ name: 'method', value: t0.method || 'Chuyển khoản', options: ['Chuyển khoản', 'Tiền mặt'] }) })}${U.field({ label: 'Ngân hàng', input: U.input({ name: 'bankName', value: t0.bankName || '' }) })}${U.field({ label: 'Chủ tài khoản', input: U.input({ name: 'bankAccountName', value: t0.bankAccountName || '' }) })}${U.field({ label: 'Số tài khoản', input: U.input({ name: 'bankAccountNo', value: t0.bankAccountNo || '' }) })}${U.field({ label: 'Nội dung CK (template)', input: U.input({ name: 'transferTemplate', value: t0.transferTemplate || '{room} - {building} - {customer_name}' }) })}${U.field({ label: 'Phạt chậm trả (đ/ngày)', input: U.money({ name: 'lateFeePerDay', value: t0.lateFeePerDay || 0 }) })}${U.field({ label: 'Grace (ngày)', input: U.input({ name: 'graceDays', type: 'number', value: t0.graceDays || 0 }) })}</div>`, footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Lưu', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { const d = m.data(); const rec = { notifyDay: Number(d.notifyDay) || 0, payFrom: Number(d.payFrom) || 0, payTo: Number(d.payTo) || 0, method: d.method, bankName: d.bankName, bankAccountName: d.bankAccountName, bankAccountNo: d.bankAccountNo, transferTemplate: d.transferTemplate, lateFeePerDay: F.num(d.lateFeePerDay), graceDays: Number(d.graceDays) || 0 }; if (pterms) St.update('contractPaymentTerms', pterms.id, rec); else St.add('contractPaymentTerms', Object.assign({ contractId: c.id, dueDay: c.payDay, source: 'manual' }, rec)); St.audit('update', 'contract', c.id, 'Cập nhật điều khoản thanh toán ' + c.code, { before: t0, after: rec }); m.close(); TH.router.refresh(); } }); },
      'edit-renewal': () => { const r0 = rclause || {}; const m = U.modal({ title: 'Điều khoản gia hạn / báo trước', size: 'sm', body: `<div class="form-grid">${U.field({ label: 'Loại', input: U.select({ name: 'renewalType', value: r0.renewalType || 'AUTO_RENEW_CLAUSE', options: [['AUTO_RENEW_CLAUSE', 'Tự gia hạn (điều khoản)'], ['MANUAL', 'Gia hạn thủ công'], ['NONE', 'Không gia hạn']] }), cls: 'span2' })}${U.field({ label: 'Kỳ gia hạn (tháng)', input: U.input({ name: 'renewalMonths', type: 'number', value: r0.renewalMonths || 12 }) })}${U.field({ label: 'Báo trước (ngày)', input: U.input({ name: 'noticeDays', type: 'number', value: r0.noticeDays || 30 }) })}${U.field({ label: 'Điều khoản gốc', input: U.textarea({ name: 'rawClause', value: r0.rawClause || '', rows: 3 }), cls: 'span2' })}</div>`, footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Lưu', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { const d = m.data(); const rec = { renewalType: d.renewalType, renewalMonths: Number(d.renewalMonths) || 0, noticeDays: Number(d.noticeDays) || 0, rawClause: d.rawClause }; if (rclause) St.update('contractRenewalClauses', rclause.id, rec); else St.add('contractRenewalClauses', Object.assign({ contractId: c.id, source: 'manual' }, rec)); St.audit('update', 'contract', c.id, 'Cập nhật điều khoản gia hạn ' + c.code, { before: r0, after: rec }); m.close(); TH.router.refresh(); } }); },
      'add-asset': () => { const m = U.modal({ title: 'Thêm tài sản bàn giao', size: 'sm', body: `<div class="form-grid">${U.field({ label: 'Tên', req: true, input: U.input({ name: 'name' }), cls: 'span2' })}${U.field({ label: 'Nhóm', input: U.select({ name: 'group', value: 'furniture', options: [['furniture', 'Nội thất'], ['device', 'Thiết bị']] }) })}${U.field({ label: 'Số lượng', input: U.input({ name: 'qty', value: '1' }) })}${U.field({ label: 'Đơn vị', input: U.input({ name: 'unit', value: 'cái' }) })}${U.field({ label: 'Tình trạng', input: U.input({ name: 'condition', value: 'Bình thường' }) })}${U.field({ label: 'Ghi chú', input: U.input({ name: 'note' }), cls: 'span2' })}</div>`, footer: U.btn({ label: 'Hủy', act: 'x' }) + U.btn({ label: 'Thêm', cls: 'btn-primary', act: 's' }) }); U.bind(m.el, { x: () => m.close(), s: () => { const d = m.data(); if (!d.name) return U.toast('warn', 'Nhập tên tài sản'); St.add('contractHandoverAssets', { contractId: c.id, roomId: c.roomId, name: d.name, group: d.group, qty: d.qty, unit: d.unit, condition: d.condition, note: d.note, source: 'manual' }); St.audit('update', 'contract', c.id, 'Thêm tài sản bàn giao ' + d.name); m.close(); TH.router.refresh(); } }); } });
